insert into org_novo.executor_tipo values ('P','Pessoa do círculo',true,false),('A','Agente',false,true),('R','Automação',false,true),('H','Pessoa de fora do círculo',true,false),('C','Outro círculo',false,false),('X','Assessoria',true,false);
insert into org_novo.circulo values (1,'Identidade','ID','ID','A Identidade padroniza, normatiza e sistematiza. Quem executa são os outros círculos, e quem audita é a Governança. São cinco jornadas: declarar quem somos, transformar isso em regra, criar as marcas, definir o posicionamento e avaliar se os padrões funcionam. O Soul Brand é a declaração de identidade em vigor: é a saída da ID-01 e serve de insumo às outras quatro.',null,'Fechado em 01/10/2026 · mudanças aprovadas aplicadas em 02/10/2026 · proposta da revisão aplicada em 03/10/2026 · auditoria de execução aplicada em 03/10/2026');
insert into org_novo.dominio (circulo,nome,descricao) values (1,'Fundamento','Dizer quem somos e transformar isso em regra aplicável.');
insert into org_novo.dominio (circulo,nome,descricao) values (1,'Marca','Criar e proteger as marcas do Ecossistema e das empresas.');
insert into org_novo.dominio (circulo,nome,descricao) values (1,'Posicionamento','Definir a promessa e as mensagens para cada público.');
insert into org_novo.dominio (circulo,nome,descricao) values (1,'Avaliação','Conferir se os padrões funcionam e decidir o que rever.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('apqc','APQC, Process Classification Framework (PCF), cross-industry','PDF da versão 7.4 (agosto de 2024) aberto em dois endereços e lido por inteiro em 01/10/2026, por extração do texto das 35 páginas, que cobrem as 13 categorias. Conferidos um a um os elementos das categorias 1, 3 e 7 (por mim e por um revisor independente) e os da categoria 2 e dos grupos 8.4, 12.4, 12.5, 13.5, 13.6 e 13.7 (por mim e por um segundo revisor, no desenho do círculo 3). Em 03/10/2026, os elementos citados das categorias 4, 5, 6, 7, 9, 10, 11 e 12 e o 13.9.2.3 (por mim e por um revisor independente em cada um dos círculos 7, 8 e 9). Também em 03/10/2026, os 18 elementos das categorias 8 e 13 citados no círculo 6, conferidos código e nome contra o texto do PDF 7.4, e os grupos de nível 2 das categorias 8 e 13, conferidos por um revisor independente no mesmo PDF. A versão 8.0 (27/02/2026) foi conferida só nas 13 categorias, na página da coleção de definições da APQC.','[["PCF 7.4 (PDF, cópia 1)", "https://www.business-analysis.com.au/wp-content/uploads/2025/04/K014750_APQC-Process-Classification-Framework-PCF-Cross-Industry-PDF-Version-7.4_January-2025.pdf"], ["PCF 7.4 (PDF, cópia 2)", "https://solutions.ifrc.org/sites/default/files/2024-10/K014750_APQC%20Process%20Classification%20Framework%20(PCF)%20-%20Cross%20Industry%20-%20PDF%20Version%207.4.pdf"], ["PCF 8.0 (página oficial)", "https://www.apqc.org/resource-library/resource-listing/apqc-process-classification-framework-pcf-cross-industry-excel-12"], ["PCF 8.0, 13 categorias", "https://www.apqc.org/resource-library/resource-collection/pcf-version-80-process-definitions-and-key-measures-collection"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'apqc','PCF 7.4. Mostra que os processos de identidade estão espalhados por estratégia (1.1.4, 1.2.1), marketing (3.2.1.2, 3.2.1.4), pessoas (7.1.1.9, 7.3.1.1, 7.5.1, 7.8) e relações externas (categoria 12.0). Não existe categoria de identidade: por isso a Identidade padroniza e os círculos donos dessas funções executam.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('collins','Jim Collins e Jerry Porras, Building Your Company’s Vision, Harvard Business Review, set.–out. 1996','Página oficial do artigo aberta; o texto completo é pago, a definição citada está visível.','[["hbr.org", "https://hbr.org/1996/09/building-your-companys-vision"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'collins','A visão tem duas partes: ideologia central (valores e propósito) e futuro imaginado. Base da ID-01.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('iso37000','ISO 37000:2021, Governance of organizations — Guidance','Página do comitê ISO/TC 309 aberta; a norma completa é paga e não foi lida.','[["committee.iso.org", "https://committee.iso.org/ISO_37000_Governance"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'iso37000','O propósito é o primeiro dos 11 princípios de governança; os valores informam o propósito e o modo de alcançá-lo. Base da aprovação pelos sócios na ID-01.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('pas808','BSI, PAS 808:2022, Purpose-driven organizations. Worldviews, principles and behaviours for delivering sustainability. Guide','Página oficial da BSI aberta (publicada em 30/07/2022); o texto completo é pago e não foi lido.','[["knowledge.bsigroup.com", "https://knowledge.bsigroup.com/products/purpose-driven-organizations-worldviews-principles-and-behaviours-for-delivering-sustainability-guide"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'pas808','Guia para organizações orientadas a propósito, incluindo prestação de contas aos públicos. Base do rascunho do relato de impacto transferido à Governança.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('quinn','Robert Quinn e Anjan Thakor, Creating a Purpose-Driven Organization, Harvard Business Review, jul.–ago. 2018','Página oficial aberta (título, autores e data); os oito passos foram conferidos em cópia do artigo hospedada pela FAO.','[["hbr.org", "https://hbr.org/2018/07/creating-a-purpose-driven-organization"], ["cópia (FAO)", "https://www.fao.org/fileadmin/templates/library/pdf/Harvard_Business_Review.pdf"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'quinn','Oito passos; usamos “descobrir o propósito”, “estimular o aprendizado individual” e “conectar as pessoas ao propósito”. Base da ID-01 e do rascunho de propósito pessoal transferido à Gestão.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('hatch','Mary Jo Hatch e Majken Schultz, Are the Strategic Stars Aligned for Your Corporate Brand?, Harvard Business Review, fev. 2001, v. 79, n. 2, p. 129–134','Página oficial aberta (texto pago); o resumo com as três lacunas foi conferido no registro da Copenhagen Business School.','[["hbr.org", "https://hbr.org/2001/02/are-the-strategic-stars-aligned-for-your-corporate-brand"], ["registro CBS", "https://research.cbs.dk/en/publications/are-the-strategic-stars-aligned-for-your-corporate-brand/"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'hatch','Marca corporativa pede alinhamento entre visão, cultura e imagem; as três lacunas são visão–cultura, imagem–cultura e imagem–visão. Base da ID-05; a ID-04 usa o relatório dessas lacunas como insumo.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('aaker','David Aaker e Erich Joachimsthaler, The Brand Relationship Spectrum, California Management Review, v. 42, n. 4, 2000','Registro do artigo aberto na Case Centre; estratégias e perguntas conferidas em cópia do artigo hospedada por terceiro. As páginas não são citadas: a cópia mostra 8–22 e há citação como 8–23.','[["The Case Centre", "https://www.thecasecentre.org/products/view?id=5390"], ["cópia do artigo", "https://ngovietliem.com/wp-content/uploads/2022/12/Reading-4.2-Brand-relationship-spectrum.pdf"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'aaker','Arquitetura de marca em quatro estratégias: casa de marcas (house of brands), marcas endossadas (endorsed brands), submarcas (subbrands) e casa com marca (branded house, em que a marca-mãe domina); perguntas para escolher. Base da etapa 2 da ID-03.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('wheeler','Alina Wheeler, Designing Brand Identity','As cinco fases foram conferidas em entrevista da autora; o livro não foi lido.','[["entrevista (Logo Geek)", "https://logogeek.uk/podcast/design-a-brand-identity-with-alina-wheeler/"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'wheeler','Processo em cinco fases: pesquisa, estratégia, desenho da identidade, pontos de contato e gestão dos ativos. Base da ID-03.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('inpi','INPI, serviço de prorrogação de registro de marca (gov.br)','Página oficial do serviço aberta. O artigo da Lei 9.279/1996 não foi conferido no texto da lei.','[["gov.br", "https://www.gov.br/pt-br/servicos/solicitar-a-prorrogacao-de-registro-de-marca-e-expedicao-de-certificado-de-registro"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'inpi','O registro de marca vale 10 anos, renováveis; a prorrogação é pedida no último ano de vigência ou em até seis meses depois. Base da etapa 5 da ID-03.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('iso20671','ISO 20671-1:2021, Brand evaluation — Part 1: Principles and fundamentals','Página oficial da ISO aberta (resumo); a norma completa é paga e não foi lida.','[["iso.org", "https://www.iso.org/standard/81739.html"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'iso20671','Avaliação de marca com elementos de entrada, dimensões de saída e indicadores. Base da ID-05.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('iso10010','ISO 10010:2022, Quality management — Guidance to understand, evaluate and improve organizational quality culture','Página oficial da ISO aberta (resumo); a norma completa é paga e não foi lida. O foco da norma é cultura de qualidade; usamos a sequência entender, avaliar e melhorar, que está no título, não o conteúdo.','[["iso.org", "https://www.iso.org/standard/38457.html"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'iso10010','Orientação para entender, avaliar e melhorar a cultura de qualidade. Usamos a sequência entender, avaliar e melhorar na ID-05.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('mckinsey','Tessa Basford e Bill Schaninger, The four building blocks of change, McKinsey, 11/04/2016','Artigo aberto no site da McKinsey.','[["mckinsey.com", "https://www.mckinsey.com/capabilities/people-and-organizational-performance/our-insights/the-four-building-blocks--of-change"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'mckinsey','Quatro alavancas para mudar comportamento: exemplo dos líderes, entendimento e convicção, desenvolvimento de habilidades e mecanismos formais. Base do kit de cultura e pessoas, na ID-02.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('schein','Edgar Schein, modelo de cultura organizacional em três níveis','Fonte secundária: verbete da Wikipédia. O livro não foi lido.','[["Wikipédia", "https://en.wikipedia.org/wiki/Edgar_Schein"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'schein','Cultura em três níveis: artefatos e comportamentos, valores declarados e pressupostos básicos. Tratar rituais como artefatos é leitura nossa; o verbete não fala em rituais. Base do padrão dos rituais, na ID-02.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('craig','Nick Craig e Scott Snook, From Purpose to Impact, Harvard Business Review, v. 92, n. 5, maio de 2014','Registro do artigo aberto no site da Harvard Business School e página do artigo na HBR (resumo); o texto completo não foi lido. As páginas não são citadas: os registros divergem entre 104–111 e 105–111.','[["hbs.edu", "https://www.hbs.edu/faculty/Pages/item.aspx?num=47372"], ["hbr.org", "https://hbr.org/2014/05/from-purpose-to-impact"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'craig','Declaração de propósito pessoal seguida de um plano para transformar o propósito em impacto. Base do rascunho de propósito pessoal transferido à Gestão.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('reptrak','RepTrak, Global RepTrak 100 (2026)','Página oficial aberta.','[["reptrak.com", "https://www.reptrak.com/globalreptrak/"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'reptrak','Sete fatores de reputação: produtos e serviços, desempenho, inovação, liderança, conduta, cidadania e ambiente de trabalho. Usados como temas da percepção dos públicos que a ID-05 recebe de Relações.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('iso22361','ISO 22361:2022, Security and resilience — Crisis management — Guidelines','Página oficial da ISO aberta (resumo); a norma completa é paga e não foi lida.','[["iso.org", "https://www.iso.org/standard/50267.html"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'iso22361','Diretrizes para a capacidade de gestão de crises. Base do protocolo de crise, que a ID-02 entrega à Governança e a Relações.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('nng','Kate Moran, The Four Dimensions of Tone of Voice, Nielsen Norman Group, 17/07/2016','Artigo aberto no site da NN/g.','[["nngroup.com", "https://www.nngroup.com/articles/tone-of-voice-dimensions/"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'nng','Quatro dimensões de tom: formal ou casual, sério ou divertido, respeitoso ou irreverente, sóbrio ou entusiasmado. Base do guia de voz na ID-02.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('google_persona','Google, Conversation Design: Create a persona','Página oficial aberta. A plataforma a que o guia se refere foi descontinuada em 13/06/2023; o método de persona continua aplicável.','[["developers.google.com", "https://developers.google.com/assistant/conversation-design/create-a-persona"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'google_persona','Passos para definir a persona de um agente de conversa. Base da persona dos agentes na ID-02.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('impact','Impact Frontiers, Five Dimensions of Impact (Impact Management Norms)','Página oficial aberta.','[["impactfrontiers.org", "https://impactfrontiers.org/norms/five-dimensions-of-impact/"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'impact','Cinco dimensões de impacto: o quê, quem, quanto, contribuição e risco. Base da definição do que conta como impacto, que a ID-02 entrega à Governança e à Estratégia.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('bpmn','OMG, Business Process Model and Notation (BPMN) 2.0.2; ISO/IEC 19510:2013','Páginas oficiais da OMG e da ISO abertas; a lista de tipos de tarefa foi conferida no BPMN Quick Guide; a atividade de chamada foi aceita pelo metamodelo usado nos testes. A especificação completa não foi lida.','[["omg.org", "https://www.omg.org/spec/BPMN/2.0.2/About-BPMN"], ["iso.org", "https://www.iso.org/standard/62652.html"], ["BPMN Quick Guide", "https://www.bpmnquickguide.com/quickguide/bpmn-quick-guide/tasks"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'bpmn','Notação dos fluxos. A ISO/IEC 19510:2013 é idêntica ao BPMN 2.0.1. Tipos de tarefa usados: usuário, manual, serviço, regra de negócio e script, além da atividade de chamada.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('camunda','Camunda, Best Practices: Naming BPMN elements','Documentação oficial aberta.','[["docs.camunda.io", "https://docs.camunda.io/docs/components/best-practices/modeling/naming-bpmn-elements/"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'camunda','Regra de nomes: tarefa com verbo no infinitivo e objeto; evento com objeto e estado; gateway com pergunta; raia com papel ou sistema.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('dmn','OMG, Decision Model and Notation (DMN)','Página oficial da OMG aberta.','[["omg.org", "https://www.omg.org/spec/DMN"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'dmn','Padrão de modelagem de decisões, que inclui tabelas de decisão e foi desenhado para uso ao lado do BPMN. Usado na ID-02 para os critérios de decisão e para a regra de uso da marca por terceiros.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('sipoc','ASQ, SIPOC+CM Diagram','Página oficial da ASQ aberta.','[["asq.org", "https://asq.org/quality-resources/sipoc"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'sipoc','Fornecedor, entrada, processo, saída e cliente: a base de “quem gera a entrada” e “quem recebe a saída” em cada etapa.');
insert into org_novo.fonte (chave,referencia,conferencia,links) values ('iia','The Institute of Internal Auditors, The IIA’s Three Lines Model: An Update of the Three Lines of Defense (2020; versão lida atualizada em setembro de 2024)','Documento oficial aberto no site do IIA. O modelo trata de governança e gestão de riscos; aplicá-lo à separação de papéis entre os círculos é analogia nossa.','[["theiia.org", "https://www.theiia.org/globalassets/documents/resources/the-iias-three-lines-model-an-update-of-the-three-lines-of-defense-july-2020/three-lines-model-updated-english.pdf"]]'::jsonb) on conflict (chave) do nothing;
insert into org_novo.fonte_uso values (1,'iia','Três linhas: a primeira está ligada à entrega de produtos e serviços; a segunda dá conhecimento especializado, apoio, monitoramento e contestação; a terceira, a auditoria interna, dá avaliação e assessoria independentes. Usado por analogia na ID-02 e na ID-05 para separar quem padroniza (Identidade), quem executa (os outros círculos) e quem audita (Governança).');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,1,'A Identidade padroniza, normatiza e sistematiza; os outros círculos executam','Regra sua (12:29), aplicada às treze jornadas por proposta minha, que você aprovou (12:59)','O círculo fica com cinco jornadas; oito são transferidas a quem executa.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,2,'O Soul Brand é insumo, não o centro das jornadas','Orientação sua (10:01)','Ele é a declaração de identidade em vigor: saída da ID-01 e entrada das demais.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,3,'Comunicação interna fica na Gestão; a externa, em Relações','Decisão sua (12:29) para a interna; a externa segue a decisão D3 da rodada 2','A Identidade entrega voz, mensagens e o aviso do que mudou.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,4,'Auditoria das entregas fica na Governança, com interoperabilidade com o que é cross','Decisão sua (12:29)','A Identidade entrega critérios de auditoria e casos de teste e julga os casos de fronteira.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,5,'Integração cultural, rituais, reconhecimento e propósito pessoal ficam na parte de cultura e pessoas da Gestão','Decisão sua (12:29), estendida por proposta minha aprovada (12:59)','A Identidade entrega o kit de cultura e pessoas.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,6,'Monitorar a reputação fica em Relações; responder a crises, na Governança com o executivo','Proposta minha aprovada (12:59)','A Identidade entrega o protocolo de crise e tem assento no comitê.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,7,'O relato de impacto fica na Governança','Proposta minha aprovada (12:59)','A Identidade define o que conta como impacto.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,8,'Material de marca é produzido por quem usa; uso por terceiros fica em Relações, com Governança','Proposta minha aprovada (12:59)','A Identidade entrega o pacote de marca com modelos e a regra de uso por terceiros.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,9,'A Identidade mantém o ciclo de retorno e responde consultas em prazo combinado','Condição proposta por mim e aprovada (12:59)','ID-05 avalia os padrões com os dados de quem mede; a etapa 1 da ID-02 responde consultas. O prazo ainda não foi definido.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,10,'Os padrões são obrigatórios','Condição proposta por mim e aprovada (12:59)','Cada jornada que executa terá um ponto de conferência contra o padrão. Vale como requisito para os próximos círculos.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,11,'Quatro ajustes depois do fechamento: marca recebida e retirada de marca (ID-03); ramo “manter o atual” quando os sócios dizem não (ID-01 e ID-02); pesquisa de mercado vinda da Inteligência (ID-03); conferência da Governança nos limites dos agentes (ID-02)','Propostas do revisor independente e do cruzamento com a Estratégia, aprovadas por você (15:48)','Aplicados nesta versão.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,12,'Reserva de domínios e registro de perfis da marca ficam na Identidade','Decisão sua (15:48), contra a proposta do revisor','A ID-03 fica como estava nesse ponto.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,13,'O posicionamento institucional e a casa de mensagens passam a ir também à Inteligência','Proposta do cruzamento com a Inteligência, aprovada por você (20:02)','A ID-04, etapa 5, entrega o posicionamento à Inteligência, que o usa para enquadrar cada oferta (IN-07, etapa 3).');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,14,'Na marca, a Identidade decide, ouvido o executivo; a retirada vale na data de efeito do pedido','Duas propostas, aprovadas por você (20:11 de 02/10/2026)','Na ID-03, etapa 4, o executivo opina e a Identidade escolhe a identidade visual e verbal; na etapa 2, a retirada da marca é agendada para a data de efeito que vem no pedido da Estratégia.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,15,'O nível “workflow” passa a se chamar etapa; cada círculo tem o seu código','Você usou “etapas” (10:01); o código por círculo é proposta minha, sem objeção','ID-01 a ID-05 aqui; ES-01 em diante na Estratégia.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,16,'Auditoria de execução: modo de cada etapa e nível de automação pelo que as tarefas fazem','Itens 1 a 14 da auditoria, aprovados por você (12:33 de 03/10/2026)','De Autopiloto para Autômato, pelas tarefas: ID-04 etapa 5. De Copiloto para Assistido, pelas tarefas: ID-01 etapa 1, ID-01 etapa 2, ID-03 etapa 2, ID-03 etapa 3, ID-03 etapa 4, ID-04 etapa 2. Nível de automação pela faixa: ID-01 baixa → média; ID-02 alta nas consultas, média na redação → média (alta nas consultas, média na redação); ID-04 média → baixa; ID-05 média → alta.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,17,'Você lidera a Identidade até os padrões estarem codificados','Tema P2, decidido por você (13:09 de 03/10/2026)','O líder do círculo Identidade é você; a troca de liderança volta a decisão quando os padrões estiverem codificados.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,18,'Critério de decisão e limites dos agentes','Aprovado por você (13:51 de 03/10/2026), a aprovar pelos sócios na ID-02','Agente sem tarefa de julgamento; etapa sem pessoa no caminho principal só em risco baixo ou médio, com auditoria por amostra no médio (P6); liberação com teste e alçada conferida pela Governança; suspensão quando a auditoria aponta desvio.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,19,'Cadências e conteúdos validados; gates de implantação','Validado por você (14:07 de 03/10/2026)','ID-05 semestral. O que depende de dado real ficou nos gates G1 a G9.');
insert into org_novo.decisao_registrada (circulo,ordem,decisao,origem,efeito) values (1,20,'Correções da auditoria geral','Aprovado por você (16:05 de 03/10/2026)','ID-02, etapa 2: a Identidade aprova voz e persona dos agentes; os limites dos agentes vão aos sócios na etapa 3, que passam a ser o dono único deles (M5).');
insert into org_novo.limite (circulo,ordem,texto) values (1,1,'Os fluxos rodam no motor próprio sobre o Supabase, por enquanto em simulação (piloto: Identidade). Falta trocar os adaptadores simulados pelos sistemas reais.');
insert into org_novo.limite (circulo,ordem,texto) values (1,2,'Não há tempo, volume nem carga por pessoa: nada disso foi medido, então nada foi estimado.');
insert into org_novo.limite (circulo,ordem,texto) values (1,3,'Com os nove círculos fechados (03/10/2026), as trocas com os outros oito foram conferidas dos dois lados pelo nome: 411 trocas, sem problema (410 até 03/10/2026, 21:05; a troca nova é o racional financeiro do contrato, de Negócios para a Gestão).');
insert into org_novo.limite (circulo,ordem,texto) values (1,4,'As conferências feitas por outros círculos não têm ramo de recusa desenhado: a recusa devolve o trabalho à tarefa anterior.');
insert into org_novo.limite (circulo,ordem,texto) values (1,5,'Na ID-02, as consultas entram pela etapa 1. Se o volume crescer, vale separar em jornada própria; hoje não há medida de volume.');
insert into org_novo.limite (circulo,ordem,texto) values (1,6,'Na ID-03, a jornada termina no pedido de registro; oposição ou recusa do registro ainda não tem caminho desenhado.');
insert into org_novo.limite (circulo,ordem,texto) values (1,7,'As oito jornadas transferidas foram assumidas pelos círculos de destino, já fechados: material de marca por quem usa a marca; integração cultural (GE-08), propósito pessoal (GE-09), rituais e reconhecimento (GE-10) e comunicação interna (GE-11) pela Gestão; comunicação externa (RE-07) e monitoramento da reputação (RE-08) por Relações; comitê de crise (GO-08), auditoria das entregas (GO-06) e relato de impacto (GO-10) pela Governança. Os rascunhos ficam aqui como histórico.');
insert into org_novo.limite (circulo,ordem,texto) values (1,8,'Os números descrevem este desenho, não a operação atual.');
insert into org_novo.jornada values ('ID-01',1,'Definir e revisar propósito, visão, missão, princípios e valores','Fundamento','essencial',1,'Manter uma declaração de identidade única, aprovada pelos sócios, que diga o que vale para todo o Ecossistema e o que é próprio de cada empresa.','Rara: por evento (empresa nova) ou quando a avaliação da ID-05 decide rever a declaração','média','Decisão humana e pouco frequente. O fluxo serve de roteiro, não de automação.',array['Estratégia','Sócios','Governança','Executivo da empresa','Identidade · pessoa','Identidade · agente','Identidade · automação']::text[]);
