insert into org_novo.evento (jornada,tipo,nome,raia,gatilho) values ('RE-01','início','Oferta aprovada para lançamento recebida','Estratégia','message');
insert into org_novo.evento (jornada,tipo,nome,raia,gatilho) values ('RE-01','início','Resposta ao pedido de recurso recebida','Gestão','message');
insert into org_novo.evento (jornada,tipo,nome,raia,gatilho) values ('RE-01','início','Revisão do plano de demanda pedida','Relações · automação','message');
insert into org_novo.evento (jornada,tipo,nome) values ('RE-01','fim','Plano de demanda aprovado e publicado');
insert into org_novo.etapa (jornada,numero,nome,dono,modo,risco,classe_real) values ('RE-01',1,'Reunir o que orienta a demanda do ciclo','Relações','Autopiloto','baixo','Autopiloto');
insert into org_novo.tarefa (etapa,ordem,nome,executor,raia,tipo_bpmn,condicao) values ((select id from org_novo.etapa where jornada='RE-01' and numero=1),1,'Reunir direção, alvos, ofertas, lançamentos, leitura de mercado e resultado anterior','R','Relações · automação','script',null);
