insert into org_novo.jornada values ('RE-07',4,'Comunicar para fora: pauta, conteúdo, imprensa e porta-vozes','Comunicação e reputação','essencial',1,'Comunicar aos públicos externos, com uma só voz e dentro dos padrões de identidade, os fatos, as mudanças, os lançamentos e os casos que importam, preparar quem fala pela empresa e medir o efeito de cada tema contra o alvo, e não só a exposição. O executivo aprova o que se diz em nome da empresa; a Governança confere o risco jurídico. A comunicação interna é da Gestão.','A cada ciclo de pauta (cadência: pauta mensal) e por evento: fato a comunicar ou pedido de imprensa','média','Reunir fatos, propor a pauta, redigir, conferir, publicar e medir são de agente e automação; decidir a pauta, revisar, aprovar e preparar os porta-vozes são de pessoas.',array['Solicitante','Executivo da empresa','Governança','Identidade','Relações · pessoa','Relações · agente','Relações · automação']::text[]);
