insert into org_novo.decisao_caminho (etapa,ordem,pergunta,quem,saidas) values ((select id from org_novo.etapa where jornada='NE-01' and numero=1),1,'O que abriu o trabalho?','Negócios · automação','[{"rotulo": "Oferta nova, preço-base alterado, resposta da Inteligência ou revisão da tabela", "via": [], "vai": "segue na etapa"}, {"rotulo": "Decisão de encerrar oferta, ainda sem data de saída", "via": ["Bloquear novas propostas da oferta, sem mudar a tabela publicada nem avisar fora"], "vai": "fim: Venda da oferta bloqueada, à espera da data de saída"}, {"rotulo": "Data de saída confirmada", "via": ["Marcar na tabela a oferta que não pode mais ser vendida, com a data"], "vai": "vai para a etapa 3"}, {"rotulo": "Material vencido ou marca retirada", "via": ["Listar o material de venda afetado e retirá-lo de uso"], "vai": "vai para a etapa 3"}]'::jsonb);
