insert into org_novo.decisao_caminho (etapa,ordem,pergunta,quem,saidas) values ((select id from org_novo.etapa where jornada='NE-05' and numero=4),1,'O que se assina?','Negócios · pessoa','[{"rotulo": "Contrato com o órgão", "via": ["Receber a homologação e a convocação para assinar o contrato", "Assinar o contrato com o órgão em nome da empresa"], "vai": "segue na etapa"}, {"rotulo": "Ata de registro de preços", "via": ["Receber a homologação e a convocação para assinar a ata", "Assinar a ata de registro de preços em nome da empresa"], "vai": "segue na etapa"}, {"rotulo": "Adesão de órgão não participante à ata", "via": ["Decidir se aceita fornecer ao órgão não participante, nas regras da ata e da lei"], "vai": "segue na etapa"}]'::jsonb);
