insert into org_novo.jornada values ('IT-02',6,'Implantar o cliente, do contrato assinado à operação','Projetos e implantação','essencial',1,'Fazer cada contrato assinado virar um cliente implantado e aceito, com um plano combinado com o cliente e com Operações, ambiente, acessos, pessoas e materiais prontos, e passado a Operações para a entrega recorrente. A Integração coordena; Operações confirma a capacidade e assume a entrega; a Gestão compra o que falta; o cliente aceita.','Por evento: contrato de cliente assinado ou com escopo novo','média','Montar o cronograma e os riscos, configurar acessos, conferir requisitos, os padrões e acompanhar são de agente e automação; combinar o plano com o cliente, implantar e conferir o aceite são de pessoas.',array['Negócios','Cliente','Operações','Gestão','Identidade','Executivo da empresa','Integração · pessoa','Integração · agente','Integração · automação']::text[]);
