insert into org_novo.jornada values ('IT-03',6,'Coordenar o lançamento da oferta aprovada','Projetos e implantação','essencial',1,'Fazer cada oferta aprovada no portão de lançamento chegar ao mercado com um plano único: quem faz o quê em Relações, Negócios, Operações, Gestão e Governança, com marcos e riscos, a prontidão conferida antes de lançar e os primeiros resultados acompanhados. A Integração coordena com o executivo da empresa; cada círculo executa a sua parte.','Por evento: oferta aprovada para lançamento','média','Montar o plano, coletar a prontidão e acompanhar os primeiros indicadores são de agente e automação; fechar o plano e decidir lançar são de pessoa da Integração, ouvido o executivo.',array['Estratégia','Relações','Negócios','Operações','Gestão','Governança','Executivo da empresa','Integração · pessoa','Integração · agente','Integração · automação']::text[]);
