insert into org_novo.jornada values ('IT-08',6,'Medir e redesenhar as jornadas ponta a ponta e manter o catálogo de jornadas','Tecnologia e jornadas','essencial',2,'Fazer cada jornada ponta a ponta ser medida, ter o gargalo achado com evidência, ser redesenhada com o círculo dono e com os círculos por onde passa, ter o redesenho decidido pelo líder do círculo dono e conferido pela Governança quando mexe em alçada, regra ou contrato, ser implantada e ter o ganho conferido; e manter o catálogo de jornadas, etapas e tarefas íntegro e versionado. A Integração mede, propõe e implanta; o líder do círculo dono decide.','A cada ciclo de melhoria (cadência: trimestral) e por evento: recomendação de melhoria, lacuna de execução ou mudança aprovada em outra jornada','alta','Medir, achar o gargalo, versionar o catálogo e conferir o ganho são de agente e automação; propor o redesenho é de pessoa da Integração; decidir é do líder do círculo dono.',array['Inteligência','Identidade','Governança','Líder do círculo','Integração · pessoa','Integração · agente','Integração · automação']::text[]);
