insert into org_novo.jornada values ('GE-04',8,'Comprar e pagar: do pedido de compra ao fornecedor e ao parceiro pagos','Finanças','essencial',1,'Fazer cada pedido de compra ser conferido contra o orçamento e a alçada; cada fornecedor ser escolhido por preço, prazo, qualidade e risco, com o contrato revisado e guardado pela Governança; cada compra ser recebida e conferida por quem pediu; cada fatura de fornecedor ser conferida com o pedido e o recebimento e paga com a aprovação do líder do círculo, que não é quem escolhe o fornecedor; cada fornecedor ser avaliado e cobrado pelas falhas; a remuneração de cada parceiro ser apurada pelo contrato e paga; e os contratos de fornecedor serem encerrados ou transferidos na saída. Quem precisa pede, inclusive a Integração nas compras da implantação e de tecnologia; a Gestão compra e paga; a Governança revisa e guarda o contrato.','Por evento: pedido de compra, fatura de fornecedor, falha ou desempenho de fornecedor apontado','média','Conferir orçamento e alçada, cotar, emitir o pedido, registrar o recebimento, conferir a fatura e pagar são de agente e automação; escolher o fornecedor, resolver divergências e cobrar a falha são de pessoa da Gestão; aprovar o pagamento é do líder do círculo.',array['Solicitante','Estratégia','Governança','Sócios','Executivo da empresa','Líder do círculo','Gestão · pessoa','Gestão · agente','Gestão · automação']::text[]);
