insert into org_novo.jornada values ('GE-07',8,'Prover pessoas: vaga, seleção, contratação, movimentação e desligamento','Pessoas e cultura','essencial',1,'Fazer cada vaga, movimentação ou desligamento pedido pelo líder, pelo plano de capacidade ou pelo mandato ser conferido contra o orçamento, o perfil do kit de cultura e a alçada; cada vaga ser preenchida por seleção pelos comportamentos esperados, com a contratação decidida pelo líder; cada pessoa ser contratada, movimentada ou desligada com o registro, a folha e os acessos atualizados; e cada pessoa nova ir à integração. O líder decide quem entra na sua equipe; a Gestão conduz e confere; o executivo decide o que passa da alçada na empresa, e o Administrador do IMTS.OS, nos círculos; os sócios decidem o desligamento de executivo ou de líder de círculo.','Por evento: pedido do líder, plano de capacidade, mandato, saída, recurso liberado','média','Registrar, conferir orçamento e perfil, divulgar, triar e atualizar registros e acessos são de agente e automação; aprovar a abertura, conferir a decisão e fazer a proposta são de pessoa da Gestão; a escolha é do líder; o desligamento, com o executivo, o Administrador do IMTS.OS ou os sócios; o acerto rescisório é pago pela folha (GE-13), com o segundo aprovador dela.',array['Líder da equipe','Pessoa','Sócios','Administrador do IMTS.OS','Executivo da empresa','Gestão · pessoa','Gestão · agente','Gestão · automação']::text[]);
