insert into org_novo.jornada values ('GE-08',8,'Integrar pessoas novas à cultura','Pessoas e cultura','essencial',1,'Fazer cada pessoa nova, ou que mudou de papel, e cada pessoa de empresa adquirida entender o propósito, os valores e os comportamentos esperados, e sentir-se parte, antes de responder sozinha pelo seu papel: trilha montada pelo papel, conduzida com o líder, vínculos iniciais e verificação de entendimento e de pertencimento, com reforço combinado quando falta. A Identidade define o kit; a Gestão integra; o líder acompanha.','Por pessoa: contratação, mudança de papel ou incorporação de empresa adquirida','média','Abrir, montar a trilha, conduzir as dúvidas, verificar e registrar são de agente e automação; combinar o reforço é de pessoa da Gestão; conversar e confirmar os comportamentos é do líder.',array['Líder da equipe','Pessoa','Gestão · pessoa','Gestão · agente','Gestão · automação']::text[]);
