insert into org_novo.jornada values ('GE-13',8,'Calcular e pagar a folha e os encargos','Pessoas e cultura','essencial',1,'Fazer cada folha ter o ponto, as variáveis, as comissões de quem vende sobre a receita recebida, os reconhecimentos e as mudanças de remuneração do período apurados a partir dos registros de pessoas, conferida pela Gestão, aprovada pelo executivo ou, nos círculos do IMTS.OS, pelo Administrador, paga no prazo e com os encargos recolhidos. A Gestão apura, confere e paga; quem aprova é outra pessoa.','A cada período de folha (cadência: mensal; salário até o quinto dia útil do mês seguinte; FGTS até o dia 20)','média','Apurar, pagar e recolher são de agente e automação; conferir a folha é de pessoa da Gestão; aprovar é do executivo ou do Administrador do IMTS.OS.',array['Executivo da empresa','Administrador do IMTS.OS','Gestão · pessoa','Gestão · agente','Gestão · automação']::text[]);
