insert into org_novo.jornada values ('GE-12',8,'Gerir os ativos, os espaços e os serviços administrativos','Ativos e administração','essencial',1,'Fazer cada pedido de ativo, de espaço ou de serviço administrativo ser atendido pela melhor opção (comprar, alugar, remanejar ativo ocioso ou recusar), decidida pela Gestão dentro do orçamento; cada ativo ser registrado com o responsável e a depreciação, mantido e inventariado; e cada ativo ocioso, perdido ou no fim da vida ser baixado (vendido, doado, reciclado ou descartado), com os dados guardados nele eliminados. A Gestão decide e controla; a compra segue a jornada de compras.','Por evento: pedido de ativo, espaço ou serviço; e a cada ciclo de manutenção e inventário (cadência: inventário anual; manutenção pelo plano de cada ativo)','alta','Avaliar o pedido, pedir a compra, registrar, programar a manutenção, inventariar e executar a baixa são de agente e automação; decidir o atendimento e o destino do ativo são de pessoa da Gestão.',array['Solicitante','Gestão · pessoa','Gestão · agente','Gestão · automação']::text[]);
