insert into org_novo.jornada values ('GO-02',9,'Secretariar as decisões dos sócios e cumprir os atos societários','Regras e decisões','essencial',1,'Fazer cada matéria que vai aos sócios chegar completa e dentro das regras, numa pauta convocada; cada decisão ser registrada em ata, com votos, responsável e prazo; cada ato societário (constituição, alteração ou encerramento de empresa) ser registrado nos órgãos; e cada decisão ter o cumprimento acompanhado e cobrado. Os círculos levam as matérias; os sócios decidem; a Governança secretaria, registra e acompanha.','No calendário dos sócios (cadência: trimestral, e por evento) e por evento: matéria levada à decisão','média','Registrar a matéria, conferir se está completa, lavrar a ata e acompanhar o cumprimento são de agente e automação; fechar a pauta, conferir a ata e fazer os registros são de pessoa da Governança; decidir é dos sócios.',array['Solicitante','Sócios','Governança · pessoa','Governança · agente','Governança · automação']::text[]);
