insert into org_novo.jornada values ('GO-03',9,'Gerir os riscos, a conformidade e os controles internos','Riscos e conformidade','essencial',1,'Fazer os riscos de cada círculo, empresa, oferta, contrato e agente serem reunidos, avaliados pela matriz e tratados por decisão; os controles internos e a conformidade serem testados; cada falha de controle ou não conformidade virar plano de remediação com dono e prazo e, quando a causa pede, regra nova ou revista; e o relatório de riscos e conformidade ir aos sócios e à Estratégia. A Governança avalia, testa e relata; os donos tratam os riscos e remediam.','A cada ciclo de riscos e conformidade (cadência: trimestral) e por evento: risco, falha de controle ou mudança relevante','média','Reunir, avaliar pela matriz, testar controles e consolidar o relatório são de agente e automação; decidir o tratamento e montar a remediação são de pessoa da Governança, com os donos; o tratamento dos riscos de nota 15 ou mais é dos sócios.',array['Sócios','Governança · pessoa','Governança · agente','Governança · automação']::text[]);
