insert into org_novo.jornada values ('GO-07',9,'Responder aos titulares de dados pessoais','Dados, crises e relatos','essencial',1,'Fazer cada pedido de titular de dados ser registrado, com a identidade do titular confirmada antes de qualquer resposta; os dados dele serem localizados no catálogo de dados, com quem os guarda; a resposta ser decidida pela Governança, no papel de encarregada, pelos direitos e pelas bases legais da LGPD, com os motivos informados quando o pedido não procede no todo ou em parte; a execução ser pedida a quem guarda os dados (Relações, na base de relacionamento, e os demais círculos); e o titular receber a resposta depois de conferido o cumprimento. A Governança decide; quem guarda o dado executa.','Por evento: pedido de titular','alta','Registrar, confirmar a identidade, localizar os dados, propor a resposta, conferir o cumprimento e responder são de agente e automação; decidir a resposta é de pessoa da Governança.',array['Solicitante','Governança · pessoa','Governança · agente','Governança · automação']::text[]);
