insert into org_novo.achado_auditoria (gravidade,tipo,onde,detalhe) values ('leve','Decisão do caminho tomada pelo agente em etapa de risco médio ou alto','ID-02 etapa 1','O padrão vigente já resolve o pedido? Conferir se é regra objetiva; se for julgamento, vai para pessoa.');
