insert into org_novo.achado_auditoria (gravidade,tipo,onde,detalhe) values ('leve','Decisão do caminho tomada pelo agente em etapa de risco médio ou alto','IN-02 etapa 1','A pergunta cabe à Inteligência e pode ser respondida no prazo? Conferir se é regra objetiva; se for julgamento, vai para pessoa.');
insert into org_novo.achado_auditoria (gravidade,tipo,onde,detalhe) values ('leve','Decisão do caminho tomada pelo agente em etapa de risco médio ou alto','IN-02 etapa 1','A pergunta vem de portão ou de caso de empresa, ou pode trazer dado pessoal ou sigiloso? Conferir se é regra objetiva; se for julgamento, vai para pessoa.');
