insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Concessão comercial de quem vende: faixa de desconto e condições de pagamento','NE-01, NE-03, NE-04, NE-05, NE-06','Negócios','Governança aprova a faixa; acima de quem vende, o executivo; acima do executivo, os sócios','Faixa da oferta = preço de tabela até o preço-base (NE-01). Quem vende: até metade da faixa. Executivo: até o preço-base e condição de pagamento fora da política. Sócios: abaixo do preço-base, exclusividade, prazo maior que o ciclo. Contrato público: o que o edital permite (aprovado em 03/10/2026, 13:51)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Recursos de aposta e limite de recursos de cada unidade do portfólio','ES-02, ES-04','Estratégia','Estratégia, dentro da alocação; acima, os sócios','Sócios fixam a reserva de apostas e o limite de cada unidade (ES-02). Estratégia: cada aposta dentro da reserva, até um terço dela. Acima: sócios (aprovado em 03/10/2026, 13:51)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Limite do ajuste de oferta em uso (o que dispensa o portão)','IN-07','Inteligência','Estratégia (decidido por você em 03/10/2026)','Dispensa o portão se: não muda o público, não muda a promessa nem o escopo principal, não reduz o preço-base, não pede capacidade nova e não muda o risco do contrato-modelo (aprovado em 03/10/2026, 13:51)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Parceria e relação institucional','RE-06','Relações','Relações, dentro da alçada; acima, os sócios','Relações: sem exclusividade, remuneração na regra dos sócios, marca pelo pacote, prazo até o fim do ciclo, sem obrigação além do orçamento do círculo. Fora disso: sócios (aprovado em 03/10/2026, 13:51)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Critérios de decisão e limites dos agentes','ID-02, IT-05, IT-06, GO-06','Identidade e Integração','Sócios aprovam (ID-02, etapa 3), dono único; a Governança confere','Agente sem tarefa de julgamento; sem pessoa no caminho só em risco baixo ou médio, com auditoria por amostra no médio; liberação com teste e alçada conferida; suspensão por desvio, confirmada por pessoa (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Cobertura de falta de capacidade','OP-01','Operações','Operações; acima, o executivo','Operações: pessoas e parceiros já contratados, dentro do orçamento. Contratação nova ou fora do orçamento: executivo, pela GE-01 (aprovado em 03/10/2026, 13:51)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Solução e compensação de reclamação','OP-04','Operações','Operações; acima, o executivo, com a Governança','Operações: refazer e crédito até o valor faturado da entrega reclamada. Acima, ou responsabilidade e indenização: executivo, com a avaliação da Governança no fluxo (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Pedido de recurso e remanejamento no orçamento','GE-01','Gestão','Gestão; acima, o executivo ou o Administrador do IMTS.OS; entre empresas, a Estratégia','Gestão: dentro do mesmo círculo e empresa, sem mudar o total. Recurso da empresa acima da alçada da Gestão: executivo. Recurso dos círculos, que são compartilhados, ou entre círculos: o Administrador do IMTS.OS. Entre empresas: Estratégia. Aumento do total: sócios (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Ação decidida no ritual de acompanhamento','GE-02','Líder do círculo','Líder do círculo; acima, o executivo','Líder: dentro do orçamento e da alçada do círculo. Acima: executivo. Muda alvo: a Estratégia decide na ES-06. Pede recurso: GE-01. Desvio grave: ES-06 (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Limite de atraso da política de cobrança','GE-03','Gestão','Gestão','Privado: cobrança no vencimento e no ciclo seguinte; na segunda fatura vencida, proposta de suspensão ao executivo. Público: lei e contrato (aprovado em 03/10/2026, 13:51)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Compra fora do orçamento e aprovação de pagamento','GE-04','Gestão','Gestão; aprova o líder do círculo; acima, o executivo','Pagamento só com pedido, recebimento e nota conferidos; quem lança não aprova: aprova o líder do círculo, inclusive o reembolso. Fora do orçamento: executivo. Acima da reserva de contingência: sócios (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Execução de aportes, distribuição e mudanças de contas','GE-05','Gestão','Gestão; aprova o líder do círculo; acima, o executivo','Gestão executa só o que os sócios decidiram. Contas e poderes bancários: executivo com a Governança; contas do IMTS.OS: Administrador do IMTS.OS com a Governança. Todo pagamento com duas pessoas (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Vaga, movimentação e desligamento','GE-07','Gestão','Gestão; acima, o executivo ou o Administrador do IMTS.OS; desligamento, o executivo com o líder','Vaga no orçamento: Gestão com o líder. Fora do orçamento: executivo. Desligamento: executivo com o líder. Executivo ou líder de círculo: sócios. Pessoas dos círculos do IMTS.OS: Administrador do IMTS.OS. Folha e remuneração: aprova o executivo, na empresa, ou o Administrador, nos círculos (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_propoe,quem_decide,valor) values ('alçada','Regra que a Governança decide sozinha','GO-01','Governança','Sócios definem o que fica na alçada da Governança','Regras que aplicam regra geral aprovada; modelos de proposta e contrato; sigilo, dados e guarda; alçada de pessoas no círculo e de agentes no critério; matriz de riscos no apetite; rateio com a Estratégia; amostra. Aos sócios: alçadas dos executivos, regras gerais, exceções, a alçada da Governança e das pessoas da Governança (os limites dos agentes vão aos sócios pela ID-02). Quem decide sai da lista, por regra (aprovado em 03/10/2026, 13:51; ajustado às 16:05)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','ID-05 · Avaliar se os padrões de identidade funcionam e decidir o que rever','Cada ciclo de avaliação','Líder do círculo Identidade','Semestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','ES-01 · Formular e revisar a estratégia do Ecossistema e de cada empresa','Cada ciclo estratégico','Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)','Anual, com revisão no meio do ciclo (método aprovado em 03/10/2026)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','ES-02 · Rever o portfólio e realocar recursos entre empresas, ofertas e apostas','Cada fechamento de período','Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)','Semestral (método aprovado em 03/10/2026)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','ES-03 · Desdobrar a estratégia em alvos e iniciativas de cada empresa e de cada círculo','Cada ciclo de alvos','Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)','Anual, com o ciclo (método aprovado em 03/10/2026)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','ES-06 · Acompanhar a execução da estratégia e corrigir o rumo','Cada revisão da estratégia','Estratégia, no calendário do método de estratégia (sócios aprovam, ES-01)','Trimestral (método aprovado em 03/10/2026)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','IN-01 · Ler o mercado, os clientes e os concorrentes e avisar das mudanças relevantes','Cada ciclo de leitura','Líder do círculo Inteligência','Mensal (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','IN-04 · Definir e medir os indicadores e publicar as análises','Cada período de medição','Líder do círculo Inteligência','Medição mensal; revisão dos indicadores anual, junto com os alvos (ES-03) (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','IN-05 · Curar as bases de conhecimento que pessoas e agentes consultam','Cada revisão da base','Líder do círculo Inteligência','Trimestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','IN-08 · Aprender com as lições e os resultados e recomendar melhorias','Cada ciclo de aprendizado','Líder do círculo Inteligência','Trimestral, antes da revisão da execução (ES-06) (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','RE-01 · Planejar a geração de demanda do ciclo por público, oferta e canal','Cada ciclo de demanda','Líder do círculo Relações','Trimestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','RE-03 · Qualificar os contatos e entregar a Negócios as oportunidades qualificadas','Cada ciclo de nutrição e revisão da base','Líder do círculo Relações','Nutrição contínua, por evento; revisão da base semestral (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','RE-04 · Desenhar a experiência do cliente: personas, mapa da jornada e padrões de experiência','Cada revisão da experiência','Líder do círculo Relações','Anual (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
insert into org_novo.parametro (tipo,nome,onde,quem_decide,valor) values ('cadência','RE-05 · Acompanhar o sucesso de cada cliente, da entrada à renovação, à expansão ou à perda','Cada ciclo de acompanhamento do cliente','Líder do círculo Relações','Trimestral, por cliente (validado em 03/10/2026, 14:07; o líder ajusta na implantação)');
