insert into org_novo.parametro (tipo,nome,onde,valor) values ('fonte','Resolução CD/ANPD nº 15/2024 (comunicação de incidente)','Prazo de comunicação à autoridade e ao titular (GO-09)','Conferida em 03/10/2026 na página oficial da ANPD e na reprodução do DOU (26/04/2024, edição 81, seção 1, p. 114): três dias úteis, contados do conhecimento de que o incidente afetou dados pessoais (arts. 6º e 9º); em dobro para o agente de pequeno porte (art. 6º, § 8º); registro por cinco anos (art. 10). Gate G5 cumprido');
insert into org_novo.parametro (tipo,nome,onde,valor) values ('fonte','Lei 14.133/2021 (registro de preços, contratos, recebimento, impugnação e recursos)','NE-05, NE-06, OP-02','Conferidos no texto oficial (Planalto) em 03/10/2026: art. 17 (caput e §§ 1º e 2º), arts. 82 a 84, 86 (inclusive o § 3º, que limita a adesão de órgão municipal), 90, 140, 141, 164 e 165. Contratação direta não lida');
insert into org_novo.parametro (tipo,nome,onde,valor) values ('fonte','Código Civil, contratos','Contrato entre empresas (OP-07, GO-05) e escrituração (GE-05)','Conferidos no texto oficial (Planalto) em 03/10/2026: arts. 389, 395, 421, 421-A, 422, 441 a 446, 475, 1.179, 1.180 e 1.194');
insert into org_novo.parametro (tipo,nome,onde,valor) values ('fonte','Leis trabalhista, fiscal e contábil','GE-05, GE-07, GE-13','Trabalhista e contábil: conferidos no texto oficial (Planalto) em 03/10/2026 os prazos de salário, férias, rescisão e ponto (CLT, arts. 74, § 2º, 145, 459, § 1º, e 477, § 6º), o FGTS (Lei 8.036, art. 15) e a escrituração. Fiscal: depende do regime tributário de cada empresa, que não está no modelo (gate G4)');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G1','Empresas','Lista das empresas do portfólio. Para cada uma: regime tributário, porte e se é agente de pequeno porte para a ANPD.','Você','Cada empresa cadastrada com regime e porte','G4, G5, rateio (GE-06), prazos em dobro da ANPD (GO-09)','aberto');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G2','Pessoas por papel','Sócios do Ecossistema e de cada empresa, executivo de cada empresa, líder de cada círculo (você na Identidade) e encarregado de dados de cada empresa. O Administrador do IMTS.OS é você (decidido em 03/10/2026)','Você e os sócios','Nenhum papel do modelo sem pessoa; ninguém acumula papéis que se fiscalizam, como lançar e aprovar o mesmo pagamento','G3, G7 e todas as alçadas com nome','aberto');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G6','Ratificação dos sócios','Os sócios ratificam o que você aprovou: método de estratégia, regras gerais de contrato, alçadas, tabela matéria × órgão, critério dos agentes (ID-02) e apetite a risco','Sócios','Ata assinada (GO-02)','Valor formal das regras; libera o G3','aberto');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G3','Valores do primeiro ciclo','Orçamento de cada empresa e círculo, reserva de apostas, limite de cada unidade, reserva de contingência e preço-base de cada oferta','Estratégia e Gestão, com aprovação dos sócios (ES-02 e ES-03 do primeiro ciclo)','Alocação e alvos aprovados pelos sócios','As alçadas que usam essas referências','aberto');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G4','Regra fiscal e folha','Tributos, obrigações acessórias e calendário de cada empresa pelo regime; convenção coletiva aplicável','Assessoria contábil e trabalhista','Calendário fiscal e de folha de cada empresa conferido pela assessoria','GE-05, GE-13','aberto');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G5','Fontes no texto oficial','Cumprido em 03/10/2026. Lei 14.133, Código Civil, CLT e Lei 8.036 conferidos no Planalto; Resolução CD/ANPD nº 15/2024 conferida na página oficial da ANPD e na reprodução do DOU (edição 81, seção 1, p. 114). Contingência: registro de fontes com espelhos e reconferência mensal (4-modelo-fonte/fontes_oficiais)','Eu, com a reconferência mensal agendada','Cada artigo citado conferido em fonte oficial, com o link na aba Fontes','Uso dos prazos em peça, contrato e política','cumprido');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G7','Motor e sistemas','Motor escolhido em 03/10/2026: nove motores próprios sobre o Supabase, sob o runtime dos runtimes, com a Identidade como piloto. As 1.555 tarefas estão ligadas a cinco sistemas, por enquanto com adaptador simulado; falta trocar cada adaptador pelo real. Construir os agentes e as automações e liberá-los pela IT-06','Integração, com você','Cada tarefa de agente ou automação tem sistema e teste aprovado; cada agente foi liberado pela IT-06','Execução real das 73 jornadas','aberto');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G8','Modelos e políticas redigidos','Textos finais dos modelos de contrato e das políticas, a partir dos rascunhos aprovados','Governança e Gestão, com a assessoria jurídica','Cada texto aprovado por quem decide, pela aba Parâmetros em aberto','Uso em cliente, fornecedor e pessoa','aberto');
insert into org_novo.gate (codigo,nome,entra,quem_fornece,criterio_saida,desbloqueia,situacao) values ('G9','Calibração','Depois de dois ciclos: medir tempo, volume e carga; rever frações, cadências e níveis de automação','Inteligência (IN-04) e Integração (IT-08)','Parâmetros revistos com dados e aprovados por quem decide','Versão 2 do modelo','aberto');
