drop schema if exists org_novo cascade;
create schema org_novo;
create table org_novo.executor_tipo (
  codigo org.executor primary key,
  nome text not null,
  e_pessoa boolean not null,
  e_maquina boolean not null
);
create table org_novo.circulo (
  numero smallint primary key,
  nome text not null unique,
  sigla text not null unique,
  prefixo text not null unique,
  descricao text not null,
  principio text,
  situacao text not null
);
create table org_novo.dominio (
  id bigint generated always as identity primary key,
  circulo smallint not null references org_novo.circulo(numero),
  nome text not null,
  descricao text,
  unique (circulo, nome)
);
create table org_novo.jornada (
  codigo text primary key,
  circulo smallint not null references org_novo.circulo(numero),
  nome text not null,
  dominio text not null,
  classe text not null check (classe in ('essencial','recomendada')),
  onda smallint not null,
  objetivo text not null,
  frequencia text not null,
  automacao_nivel text not null,
  automacao_motivo text not null,
  raias text[] not null
);
create table org_novo.evento (
  id bigint generated always as identity primary key,
  jornada text not null references org_novo.jornada(codigo) on delete cascade,
  tipo text not null check (tipo in ('início','fim')),
  nome text not null,
  raia text,
  gatilho text
);
create table org_novo.etapa (
  id bigint generated always as identity primary key,
  jornada text not null references org_novo.jornada(codigo) on delete cascade,
  numero smallint not null,
  nome text not null,
  dono text not null,
  modo org.modo not null,
  risco org.risco not null,
  classe_real text not null,
  unique (jornada, numero)
);
create table org_novo.tarefa (
  id bigint generated always as identity primary key,
  etapa bigint not null references org_novo.etapa(id) on delete cascade,
  ordem smallint not null,
  nome text not null,
  executor org.executor not null references org_novo.executor_tipo(codigo),
  raia text not null,
  tipo_bpmn text,
  condicao text,
  unique (etapa, ordem)
);
create table org_novo.decisao_caminho (
  id bigint generated always as identity primary key,
  etapa bigint not null references org_novo.etapa(id) on delete cascade,
  ordem smallint not null,
  pergunta text not null,
  quem text not null,
  saidas jsonb not null
);
create table org_novo.entrada (
  id bigint generated always as identity primary key,
  etapa bigint not null references org_novo.etapa(id) on delete cascade,
  produto text not null,
  origem text not null
);
create table org_novo.saida (
  id bigint generated always as identity primary key,
  etapa bigint not null references org_novo.etapa(id) on delete cascade,
  produto text not null,
  destinos text[] not null
);
create table org_novo.troca (
  id bigint generated always as identity primary key,
  produto text not null,
  de_circulo text not null references org_novo.circulo(nome),
  para_circulo text not null references org_novo.circulo(nome),
  via text,
  sai_em text[] not null,
  entra_em text[] not null
);
create table org_novo.cadeia (
  codigo text primary key,
  nome text not null,
  dono text,
  nota text,
  circulos text[] not null,
  jornadas text[] not null
);
create table org_novo.cadeia_elo (
  id bigint generated always as identity primary key,
  cadeia text not null references org_novo.cadeia(codigo) on delete cascade,
  ordem smallint not null,
  de_jornada text not null references org_novo.jornada(codigo),
  para_jornada text not null references org_novo.jornada(codigo),
  produtos text[] not null
);
create table org_novo.fonte (
  chave text primary key,
  referencia text not null,
  conferencia text not null,
  links jsonb not null
);
create table org_novo.fonte_uso (
  circulo smallint not null references org_novo.circulo(numero),
  fonte text not null references org_novo.fonte(chave),
  uso text not null,
  primary key (circulo, fonte)
);
create table org_novo.jornada_fonte (
  jornada text not null references org_novo.jornada(codigo) on delete cascade,
  fonte text not null references org_novo.fonte(chave),
  primary key (jornada, fonte)
);
create table org_novo.decisao_registrada (
  id bigint generated always as identity primary key,
  circulo smallint not null references org_novo.circulo(numero),
  ordem smallint not null,
  decisao text not null,
  origem text not null,
  efeito text not null
);
create table org_novo.limite (
  id bigint generated always as identity primary key,
  circulo smallint not null references org_novo.circulo(numero),
  ordem smallint not null,
  texto text not null
);
create table org_novo.parametro (
  id bigint generated always as identity primary key,
  tipo org.tipo_parametro not null,
  nome text not null,
  onde text,
  quem_propoe text,
  quem_decide text,
  valor text,
  unique (tipo, nome)
);
create table org_novo.gate (
  codigo text primary key,
  nome text not null,
  entra text not null,
  quem_fornece text not null,
  criterio_saida text not null,
  desbloqueia text not null,
  situacao org.situacao_gate not null default 'aberto'
);
create table org_novo.achado_auditoria (
  id bigint generated always as identity primary key,
  gravidade text not null,
  tipo text not null,
  onde text not null,
  detalhe text not null
);
-- Implantação: nascem vazias (gates G1 e G2)
create table org_novo.empresa (
  id uuid primary key default gen_random_uuid(),
  nome text not null unique,
  regime_tributario text,
  porte text,
  agente_pequeno_porte boolean,
  criado_em timestamptz not null default now()
);
create table org_novo.pessoa (
  id uuid primary key default gen_random_uuid(),
  nome text not null,
  email text unique,
  criado_em timestamptz not null default now()
);
create table org_novo.atribuicao (
  id uuid primary key default gen_random_uuid(),
  pessoa uuid not null references org_novo.pessoa(id) on delete cascade,
  papel text not null check (papel in ('sócio','executivo','líder de círculo','pessoa do círculo','encarregado de dados','assessoria')),
  circulo smallint references org_novo.circulo(numero),
  empresa uuid references org_novo.empresa(id),
  inicio date not null default current_date,
  fim date
);
create index on org_novo.jornada (circulo);
create index on org_novo.etapa (jornada);
create index on org_novo.tarefa (etapa);
create index on org_novo.tarefa (executor);
create index on org_novo.decisao_caminho (etapa);
create index on org_novo.entrada (etapa);
create index on org_novo.saida (etapa);
create index on org_novo.evento (jornada);
create index on org_novo.cadeia_elo (cadeia);
create index on org_novo.cadeia_elo (de_jornada);
create index on org_novo.cadeia_elo (para_jornada);
create index on org_novo.jornada_fonte (fonte);
create index on org_novo.fonte_uso (fonte);
create index on org_novo.decisao_registrada (circulo);
create index on org_novo.limite (circulo);
create index on org_novo.atribuicao (pessoa);
create index on org_novo.atribuicao (circulo);
create index on org_novo.atribuicao (empresa);

